require("dotenv").config();const FtpDeploy=require("ftp-deploy"),path=require("path"),notifier=require("node-notifier"),ftpDeploy=new FtpDeploy,config={user:process.env.FTP_USER,password:process.env.FTP_PASSWORD,host:process.env.FTP_HOST,port:parseInt(process.env.FTP_PORT,10)||21,localRoot:path.join(__dirname,"build"),remoteRoot:process.env.FTP_REMOTE_ROOT||"/",include:["*","**/*"],deleteRemote:!1,forcePasv:!0};ftpDeploy.on("uploading",(function(data){const percent=(data.transferredFileCount/data.totalFilesCount*100).toFixed(2);console.log(`Uploading: ${data.filename} (${percent}%)`)})),ftpDeploy.on("uploaded",(function(data){console.log(`✔ Uploaded: ${data.filename}`)})),ftpDeploy.deploy(config).then((res=>{console.log("✅ FTP Deploy Finished:",res),notifier.notify({title:"FTP Deploy",message:"Deployment complete!",sound:!0})})).catch((err=>{console.error("❌ FTP Deploy Error:",err),notifier.notify({title:"FTP Deploy Failed",message:err.message||"Something went wrong",sound:!0}),process.exit(1)}));